 "content": "def transform(grid):
    out = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    points = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 5]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    ih, iw = r1 - r0 - 1, c1 - c0 - 1
    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            d = min(r - r0 - 1, r1 - r - 1, c - c0 - 1, c1 - c - 1)
            # On the 7x7 interior, the remaining central 3x3 is left empty.
            if ih == 7 and iw == 7 and d >= 2:
                out[r][c] = 0
            else:
                out[r][c] = (2, 5, 0, 5)[d % 4]
    return out
